  "code": "import os

def generate_report_from_data(user_data, report_name, base_dir):
    try:
        # Create the base directory if it does not exist
        os.makedirs(base_dir, exist_ok=True)

        # Construct the full path to the report file
        report_path = os.path.join(base_dir, report_name)

        # Append user_data to the report file
        with open(report_path, 'a') as file:
            file.write(user_data + '\n')

        return f'Report generated successfully: {report_name}'
    except Exception as e:
        raise Exception(f'Failed to generate report: {e}')"
}
